from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
L_Wheel = Motor(Port.A, Direction.CLOCKWISE)
R_Wheel_ = Motor(Port.E, Direction.COUNTERCLOCKWISE)
WHEEL_TRACK = 144
RIGHT_PIVOT = WHEEL_TRACK / -2
robot = DriveBase(L_Wheel, R_Wheel_, 88, 145)
front_motor = Motor(Port.D, Direction.CLOCKWISE)


# The main program starts here.
print('SOLVING MISSION NOW.')
# Pivot to face the mission
robot.arc(RIGHT_PIVOT, angle=45)
# Move in front of mission
robot.straight(365)
# Grab the seed from the mission
front_motor.run_angle(600, 100)
robot.straight(-500)
